function ipKeBiner(ip) {
  const bagian = ip.split(".");
  if (bagian.length !== 4) return null;
  const hasil = [];
  for (const b of bagian) {
    const n = Number(b);
    if (!/^\d+$/.test(b) || n > 255) return null;
    hasil.push(n.toString(2).padStart(8, "0"));
  }
  return hasil.join(".");
}

