solution.code:
function ipKeAngka(ip) {
  return ip.split(".").reduce((acc, o) => acc * 256 + Number(o), 0);
}

function angkaKeIp(n) {
  return [n >>> 24, (n >>> 16) & 255, (n >>> 8) & 255, n & 255].join(".");
}

function hitungSubnet(cidr) {
  const [ip, p] = cidr.split("/");
  const prefix = Number(p);
  const mask = (0xFFFFFFFF << (32 - prefix)) >>> 0;
  const network = (ipKeAngka(ip) & mask) >>> 0;
  const broadcast = (network | (~mask >>> 0)) >>> 0;
  return {
    network: angkaKeIp(network),
    broadcast: angkaKeIp(broadcast),
    mask: angkaKeIp(mask),
    pertama: angkaKeIp(network + 1),
    terakhir: angkaKeIp(broadcast - 1),
    host: 2 ** (32 - prefix) - 2,
  };
}

function bagiSubnet(cidr, jumlah) {
  if (!Number.isInteger(jumlah) || jumlah < 1 || (jumlah & (jumlah - 1)) !== 0) return null;
  const [ip, p] = cidr.split("/");
  const baru = Number(p) + Math.log2(jumlah);
  if (baru > 30) return null;
  const awal = ipKeAngka(hitungSubnet(cidr).network);
  const ukuran = 2 ** (32 - baru);
  const hasil = [];
  for (let i = 0; i < jumlah; i++) {
    hasil.push(hitungSubnet(angkaKeIp(awal + i * ukuran) + "/" + baru));
  }
  return hasil;
}

function satuSubnet(ip1, ip2, prefix) {
  const mask = prefix === 0 ? 0 : (0xFFFFFFFF << (32 - prefix)) >>> 0;
  return ((ipKeAngka(ip1) & mask) >>> 0) === ((ipKeAngka(ip2) & mask) >>> 0);
}

function jenisIP(ip) {
  const [a, b] = ip.split(".").map(Number);
  if (a === 127) return "loopback";
  if (a === 10) return "privat";
  if (a === 172 && b >= 16 && b <= 31) return "privat";
  if (a === 192 && b === 168) return "privat";
  return "publik";
}
